const jsonAssets: {[key: string]: string} = {
  'Conditionals_V1.json':
    '{"description":"This video introduces the concept of conditional statements in programming. It explains that a conditional is a decision point that tells the computer to execute certain code only if a specific condition is true. Using Python as an example, it covers the syntax of the if statement, the importance of the colon, and how indentation defines which lines of code belong to the conditional block.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Hi there! This is a quick byte on Conditionals.","duration":"3.51s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"So, what exactly is a conditional statement? It tells your computer to do something only if a certain condition is true. Think of it like a decision point in your code.","duration":"12.05s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"In Python, we use the word \'if\' to tell the computer to check something - a condition. The steps that follow will only run if that condition is true.","duration":"9.75s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"This part, \'isabel dot can move south\', is our condition. The program will check if Isabel can move south. If this is true, then the steps that come next will run.","duration":"11.16s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Notice the colon after the condition. This colon tells Python that the next indented lines are part of this \'if\' block.","duration":"7.75s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"These two lines, \'isabel dot move\' and \'isabel dot paint blue\', are indented. This means they are connected to our \'if\' statement. They will only run if the condition is true.","duration":"12.69s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Indentation is super important in Python! If these lines weren\'t indented, they wouldn\'t be part of the \'if\' block and would always run, no matter if Isabel could move south or not.","duration":"11.37s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
  'Functions_With_Parameters_V1.json':
    '{"description":"This video explains functions with parameters by using the analogy of a \\"fill-in-the-blank\\" sentence. It defines a parameter as a placeholder (the blank space) and an argument as the actual value provided to fill that space. The lesson highlights that parameters are used to make code more reusable and easier to understand by allowing the same function to work with different values.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Hi there! This is a quick byte about functions with parameters.","duration":"5.08s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"So, what exactly is a parameter? A parameter is a placeholder that you put inside your function. Think of it as a blank space waiting for information.","duration":"9.43s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"In this example, \'name\' is our parameter. It\'s the placeholder inside the parentheses when we define our function on line one.","duration":"8.75s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Now, what about an argument? An argument is the actual value you give to a function when you use it. You can think of your function like a fill-in-the-blank sentence. The parameter is the blank space, and the argument is the word you choose to put into that blank.","duration":"16.74s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Here, \'Taylor\' is the argument. It\'s the actual value we pass into the function. When the function runs, this argument \'Taylor\' replaces the parameter \'name\'.","duration":"11.19s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Why do we use parameters? Well, they let you reuse the same function for many different values without having to write new code each time. This makes your code much easier to update and understand.","duration":"12.79s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
  'If_Else_V1.json':
    '{"description":"This video builds upon basic conditionals by introducing two-way selection using the if-else statement. It explains that while a simple if statement is a one-way selection (it does nothing if the condition is false), the else keyword provides an alternative path. It uses a real-world analogy of finishing homework to illustrate how the program skips the if block and runs the else block when a condition is not met.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Hi there! This is a quick byte on if-else statements.","duration":"4.09s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"An if statement lets your program make a decision. It checks a condition. If that condition is true, the code inside the if block runs. If the condition is false, the program skips that block and does nothing.","duration":"13.91s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Two-way selection, also known as an if-else statement, is when your program chooses one path or the other depending on the condition.","duration":"8.79s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"We already know how this part works. The Painter checks whether it\'s on a bucket. If that\'s true, Marie takes the paint. This part, the if statement, is a one-way selection, meaning something happens only if the condition is true.","duration":"14.62s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Now we\'re adding something new: the keyword else. This tells the program, \'If the condition is false, do this instead.\' Think of it like this: \'If I finish my homework, I\'ll go outside. Else, I\'ll stay in and work.\'","duration":"14.35s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"This is the else block. The program only runs this line if the Painter is not on a bucket. So, if the condition is false, it skips the if block and runs the else block instead.","duration":"12.74s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Just like with if statements, the else block also needs to be indented. This tells the computer what belongs to that branch of the code.","duration":"9.01s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
  'Functions_V1.json':
    '{"description":"This video provides an overview of functions, describing them as named blocks of code designed to perform specific tasks. It walks through the steps of defining a function using the def keyword, naming it, and using proper syntax (parentheses, colons, and indentation). Finally, it explains how to call a function to execute the instructions stored inside its definition.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Welcome! This is a quick byte about functions.","duration":"3.61s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"So, what exactly is a function? A function is a named block of code that performs a specific task. They are incredibly useful because they allow us to reuse code and organize our programs more efficiently. Let\'s see how functions work in code.","duration":"18.11s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Here\'s a simple Python program that uses a function to print the greeting \\"hello world\\" to the screen. We\'ll go through this program step by step to understand how it works.","duration":"11.13s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"The first step is to define your function, which is where you give it a name and specify the commands you want it to run. We use the keyword \\"def\\" to indicate that we are defining a new function.","duration":"12.46s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Next, we give our function a descriptive name. In this example, our function is called \\"greet\\".","duration":"6.53s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"When we define a function, we always include parenthesis and a colon. The colon tells the program we\'re about to enter the specific steps of our function.","duration":"10.03s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"After the definition, each line of our function needs to be indented - otherwise we\'ll get a syntax error. This function just has one line: it\'ll print \\"Hello World\\".","duration":"10.57s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Once we\'ve defined our function, the next step is to call it. You do that by typing the name of the function with its parenthesis. In our case, we\'d type \\"greet\\" with an open and close parenthesis.\\n\\n","duration":"12.55s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"When the program runs and gets to this function, it will look up it\'s definition from earlier in the program...","duration":"8.57s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"And then run the code inside the definition. In this case, it would print Hello World.","duration":"4.77s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
  'Variables_V1.json':
    '{"description":"This video covers the basics of variables, describing them as labeled containers or boxes that store information in memory. It introduces three fundamental data types: Integers (Ints), Strings, and Booleans. The speech explains how to assign values using the equal sign and how to use the print function to output these values by referencing the variable name without quotes.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Hi, this is a quick byte about Variables.","duration":"4.64s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"So what is a variable? A variable is a container that stores a value in memory. Think of it like a labeled box that holds information, like a score or username.","duration":"13.40s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Variables have different data types. Three important ones are Ints, which are like numbers; Strings, which are like words and sentences; and Booleans, which can be either true or false. Let\'s see how variables work in code.","duration":"16.25s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"This is a program that creates two variables, then prints them to the console. Let\'s go through step by step.","duration":"7.85s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"First, we create our variable and give it a name. This one is called username.","duration":"4.63s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Then we use the equal sign to assign it a value. In this case, we\'re assigning it the String value \'Kai\'. You can tell it\'s a string because of the quotes.","duration":"11.01s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Next, we\'re making another variable called level and assigning the integer value four. If you were to read this line out loud, you could say \'level gets the value four\'.","duration":"10.47s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Now we\'re using the print function to make text appear in the console. First, it\'ll print the string \'User:\'.","duration":"7.57s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Then we use a comma to tell it to print the username variable. When the program runs, it\'ll take the value from our username variable and use that to print.","duration":"11.18s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"The same thing happens with the next print line. First it prints the string \'Level:\' with a colon, and then it prints the value of our level variable, which is four.","duration":"10.87s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Notice that when you use variables, you don\'t put any quotes around them. That\'s what tells the computer to use the variable\'s value rather than the actual variable name.","duration":"10.77s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
  'While_Loops_V1.json':
    '{"description":"This video explains the While Loop, a structure used to repeat instructions to keep code clean and organized. It uses a flowchart analogy to show how a computer checks a condition: if the condition is true, the code inside the loop runs; if false, the computer exits the loop. The video also covers the Python syntax for while loops, emphasizing the keyword while, the condition, and the required indentation for the repeated steps.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Hi, this is a quick byte about While Loops.","duration":"3.53s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"So, what exactly is a Loop? A loop is a way to tell a computer to repeat a set of instructions. Instead of writing \\"talia dot move\\" seven times, a loop lets us write it only once and repeat it. This makes your code much cleaner and more organized.","duration":"17.53s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Loops need a rule to know when to stop. This rule is called a Condition. A condition is a rule that the computer checks to decide if it should keep going. It will always be either True or False. In our example, the condition is \\"talia dot can move\\", which is True if Talia can move, or False if she can\'t.","duration":"21.84s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"One way to think about a while loop is like a flowchart. The computer checks the condition first at the top.","duration":"6.83s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"While the condition is True, the code inside the loop runs.","duration":"3.71s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"After running the code, it loops back and checks the condition again. It keeps doing this, over and over, until the condition is no longer True.","duration":"9.66s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"When the condition is False, the computer skips the indented code and exits the loop.","duration":"5.64s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Now let\'s see a while loop in code. The first step is to write the keyword while.","duration":"5.64s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"The next step is to write our condition and a colon. The condition here is \\"talia dot can move\\".","duration":"6.82s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Just like with functions, the code we want to repeat must be indented. This tells the computer that these instructions are inside the loop.","duration":"10.76s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"In this loop, we want Talia to move, and after she moves, we want her to paint purple. The computer will keep doing both of these steps as long as the condition is True.","duration":"11.11s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
  'Painter_Object_V1.json':
    '{"description":"This video introduces the \\"Painter\\" object used in certain code.org python levels. It explains the relationship between a class (the blueprint) and an object (the specific instance, like \'alice\' or \'bob\'). It defines attributes as things the object knows and methods as actions it can perform. Finally, it demonstrates the \\"dot operator\\" syntax used to call methods on a specific object.","audio":"data:audio/mpeg;base64,","scenes":[{"speech":"Welcome! This is a quick byte about getting started with the Painter object.","duration":"5.12s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Think of the Painter like an assistant we control in our code. The Painter already knows how to do certain things, like moving, turning, and painting.","duration":"10.67s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"When you create a Painter, you\'re making a new object from the Painter class. This is kind of like making a custom version from a blueprint. Here\'s what this looks like when you type it in your code.","duration":"13.21s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"The Painter() part tells Python to create a new object using the Painter blueprint.","duration":"7.02s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"The \'alice =\' part gives that new object a name so we can refer to it in our code.","duration":"6.89s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"A class is like a blueprint or a set of instructions for creating something that can do specific tasks. So, when we write \'alice equals Painter\', we\'re telling Python to use the Painter blueprint to create a new painter named alice.","duration":"16.00s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"Once you\'ve created a Painter, it becomes an object. An object is something that has attributes, which are things it knows, like its location or direction. It also has methods, which are things it can do, like turning left or moving.","duration":"16.46s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"You can create multiple Painter objects. This new object, \'alice\', has everything a Painter knows how to do: move, turn, paint. But it\'s its own object! If you later create another painter called \'bob\', \'bob\' and \'alice\' are completely separate Painters. They can have different positions, directions, and even different amounts of paint.","duration":"24.23s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"To review, A method is an action that an object can do.","duration":"5.32s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"To tell an object to do something, you call one of its methods. For example, \'alice dot move\' tells the \'alice\' object to move.","duration":"8.15s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"The dot operator, which is just a period, is used to call a method that belongs to a specific object.","duration":"8.80s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"},{"speech":"After the method name, we always include a set of parentheses. This tells Python that you want to run the instructions for that method.","duration":"9.26s","html":"<html><body><img style=\\"width: 100%\\" src=\\"data:image/png;base64,\\" /></body></html>"}]}',
};

export default jsonAssets;
